export function gamma(x) {
  return 'GAMMA:' + String(x);
}

// Not imported by the app, but surfaced through `export *` — the analyzer
// must retain it (export-star widens), and test.mjs calls it directly to
// prove it survived reduction.
export function delta(values) {
  const nums = (Array.isArray(values) ? values : [values])
    .map((v) => Number(v))
    .filter((n) => Number.isFinite(n));
  if (nums.length === 0) {
    return { count: 0, sum: 0, mean: null, min: null, max: null, variance: null };
  }
  let sum = 0;
  let min = Infinity;
  let max = -Infinity;
  for (const n of nums) {
    sum += n;
    if (n < min) min = n;
    if (n > max) max = n;
  }
  const mean = sum / nums.length;
  let sq = 0;
  for (const n of nums) {
    sq += (n - mean) * (n - mean);
  }
  return { count: nums.length, sum, mean, min, max, variance: sq / nums.length };
}
